(()=>{'use strict';
const disclaimer='Disclaimer: Lead counts represent local homeowners who registered interest and requested service availability on our platform. Mow Matter does not guarantee conversion, booking, or individual project retention from these sign-ups.';
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(c/100);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(body,billing=false){await MM.ensureSession();const url=billing?'https://mowmatter-property.onrender.com/api/billing/lead-package':'https://pzymmsfjgspvzbivzvkx.supabase.co/functions/v1/mowmatter-growth';const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',apikey:'sb_publishable_KQGD-vWlAlJi_Bv7fSaEvA_YLJpIgyu',Authorization:'Bearer '+MM.session.access_token},body:JSON.stringify(body),signal:AbortSignal.timeout(billing?60000:30000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Please try again');return d;}
window.showMowGrowth=async company=>{
 const main=document.getElementById('main');main.innerHTML=`<div class="page-head"><div><p class="eyebrow">GROW YOUR SERVICE AREA</p><h1>Lead Generation &amp; Expansion</h1></div></div><section class="card demand-card" aria-labelledby="demand-title"><h2 id="demand-title">Unlock Nearby Demand</h2><p>Find homeowners who requested lawn care where no provider was available.</p><form id="demand-form" class="demand-form"><label>ZIP Code<input id="demand-zip" name="zip" type="text" inputmode="numeric" autocomplete="postal-code" pattern="[0-9]{5}" maxlength="5" required></label><label>Radius<select id="demand-radius" name="radius"><option value="15">15 miles</option><option value="25">25 miles</option></select></label><button class="button primary" id="demand-scan" disabled>Scan Area</button></form><div id="demand-status" role="status" aria-live="polite">Loading your business ZIP…</div><div id="demand-registration"></div><div id="demand-result"></div><p class="lead-disclaimer">${disclaimer}</p><p class="help">Distances are approximate straight-line distances between ZIP centers. Only requests from the past 30 days are included. Leads are shared inquiries, not exclusive bookings.</p><div id="demand-leads"></div></section>`;
 const $=id=>document.getElementById(id);let profile={business_zip:""},result,scanVersion=0,scanning=false;
 const setStatus=t=>{$('demand-status').textContent=t;};
 function resetResult(){scanVersion++;result=null;$('demand-result').replaceChildren();$('demand-leads').replaceChildren();setStatus('Scan this area to see current demand.');}
 $('demand-zip').oninput=resetResult;$('demand-radius').onchange=resetResult;
 async function scan(offset=0){if(scanning||!$('demand-form').reportValidity())return;scanning=true;const v=++scanVersion,zip=$('demand-zip').value,radius=Number($('demand-radius').value);$('demand-scan').disabled=true;$('demand-result').replaceChildren();$('demand-leads').replaceChildren();result=null;setStatus('Scanning local demand…');try{const d=await request({action:'scan',company_id:company,zip,radius,offset});if(v!==scanVersion)return;result=d;setStatus('');renderResult();}catch(e){if(v===scanVersion)setStatus(e.name==='TimeoutError'?'The scan took too long. Please try again.':e.message);}finally{scanning=false;$('demand-scan').disabled=false;}}
 $('demand-form').onsubmit=e=>{e.preventDefault();void scan();};
 function renderResult(){const d=result;let access='';if(d.unlocked)access=`<p class="lead-access">${d.access_reason==='subscription'?'Included free with your paid plan':d.access_reason==='onboarding'?'Your initial local leads are free':d.access_reason==='combined'?'Your initial and purchased leads are unlocked':'Purchased leads unlocked'} · ${d.unlocked_count} available</p>`;const locked=d.unlocked_count<d.count;
 $('demand-result').innerHTML=`<p class="demand-count">There are <strong>${d.count}</strong> homeowners in your area waiting for a provider.</p>${access}${locked?'<button class="button primary" id="demand-unlock">Unlock These Leads</button>':''}${d.count===0?'<p>No matching homeowner sign-ups yet. Try 25 miles or another ZIP.</p>':''}`;
 if(locked)$('demand-unlock').onclick=unlock;
 $('demand-leads').innerHTML=`${d.leads.length?'<h3>Your unlocked leads</h3><div class="lead-grid">'+d.leads.map(l=>`<article class="lead-card"><h4>${esc(l.first_name||'Homeowner')}</h4><p>${esc(l.address)}<br>${esc(l.city)}, ${esc(l.state)} ${esc(l.zip)}</p><p>${esc((l.services||[]).join(', '))} · ${esc(l.frequency.replaceAll('_',' '))}</p><p>${esc(l.distance_miles)} miles · ZIP estimate<br>Requested ${esc(new Date(l.created_at).toLocaleDateString())}</p><p><a href="mailto:${esc(l.email)}">${esc(l.email)}</a>${l.phone?'<br>'+esc(l.phone):''}</p></article>`).join('')+'</div>':''}<div class="actions">${d.offset>0?'<button class="button" id="leads-prev">Previous leads</button>':''}${d.offset+d.leads.length<d.unlocked_count?'<button class="button" id="leads-next">Next leads</button>':''}</div>`;
 $('leads-prev')?.addEventListener('click',()=>scan(Math.max(0,d.offset-50)));$('leads-next')?.addEventListener('click',()=>scan(d.offset+50));
 }
 function unlock(){const d=result;const dialog=document.getElementById('dialog'),content=document.getElementById('dialog-content');content.innerHTML=`<h2>Unlock These Leads</h2>${!d.onboarding_complete?'<p>Sign Up Incentives: complete your full registration to unlock your initial local leads for free.</p><button class="button primary full" id="lead-register">Complete registration — free</button>':`<p>Your registration incentive covers the initial bundle near your business ZIP${profile?.profile?.initial_zip?' '+esc(profile.profile.initial_zip):''}. Ongoing demand and expansion areas are included free with Grow or Scale.</p>`}<p><a class="button full" href="billing.html">View Grow &amp; Scale plans</a></p><p>One-off package: <strong>${money(d.package_amount_cents)}</strong> for ${d.package_count} additional homeowner${d.package_count===1?'':'s'}. $5 per lead, capped at $39. Already unlocked leads are excluded.</p><button class="button full" id="lead-buy">Buy Lead Generation Package — ${money(d.package_amount_cents)}</button><p class="lead-disclaimer">${disclaimer}</p><p id="lead-buy-status" role="status" aria-live="polite"></p>`;dialog.showModal();$('lead-register')?.addEventListener('click',onboard);$('lead-buy').onclick=async()=>{const button=$('lead-buy');button.disabled=true;try{const d=await request({company_id:company,zip:result.zip,radius:result.radius},true);const url=new URL(d.url);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw Error('Unexpected checkout destination');location.assign(url.href);}catch(e){$('lead-buy-status').textContent=e.message;button.disabled=false;}};}
 function showRegistration(){$('demand-registration').innerHTML=profile.profile?'<p class="help">Business ZIP: '+esc(profile.business_zip)+' · <button type="button" class="text-button" id="growth-register">Update business details</button></p>':'<p>Complete registration to unlock your initial local bundle free.</p><button type="button" class="button" id="growth-register">Complete business registration</button>';$('growth-register').onclick=onboard;}
 function onboard(){const dialog=document.getElementById('dialog');if(!dialog.open)dialog.showModal();const content=document.getElementById('dialog-content');content.innerHTML=`<h2>Complete your registration</h2><p>Confirm your email and save your business details to unlock one initial local lead bundle for free.</p><form id="growth-onboard" class="form"><label>Contact name<input name="contact_name" required minlength="2" maxlength="100" autocomplete="name"></label><label>Phone<input name="phone" required type="tel" maxlength="32" autocomplete="tel"></label><label>Business ZIP<input name="zip" required pattern="[0-9]{5}" inputmode="numeric" maxlength="5" autocomplete="postal-code" value="${esc(profile.business_zip||$('demand-zip').value)}"></label><fieldset><legend>Services you provide</legend>${['mowing','edging','hedges','leaves','cleanup','mulch'].map(s=>`<label class="check"><input type="checkbox" name="services" value="${s}">${s[0].toUpperCase()+s.slice(1)}</label>`).join('')}</fieldset><label class="check"><input name="accept_terms" type="checkbox" required>I agree to the <a href="https://mowmatter.com/terms.html" target="_blank" rel="noopener">Terms</a> and have reviewed the <a href="https://mowmatter.com/privacy.html" target="_blank" rel="noopener">Privacy Policy</a>.</label><p role="status" aria-live="polite"></p><button class="button primary">Complete registration &amp; scan my area</button></form>`;
 $('growth-onboard').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,b=e.submitter,f=new FormData(form);b.disabled=true;try{const services=f.getAll('services');if(!services.length)throw Error('Select at least one service');await request({action:'onboard',company_id:company,contact_name:f.get('contact_name'),phone:f.get('phone'),zip:f.get('zip'),services,accept_terms:f.has('accept_terms')});profile=await request({action:'profile',company_id:company});$('demand-zip').value=profile.business_zip;showRegistration();document.getElementById('dialog').close();await scan();}catch(e){form.querySelector('[role="status"]').textContent=e.message;}finally{b.disabled=false;}};
 }
 try{profile=await request({action:'profile',company_id:company});if(document.body.dataset.page!=='growth')return;const p=new URLSearchParams(location.search),zip=p.get('zip');$('demand-zip').value=/^[0-9]{5}$/.test(zip||'')?zip:profile.business_zip;$('demand-radius').value=p.get('radius')==='25'?'25':'15';$('demand-scan').disabled=false;showRegistration();setStatus(p.get('checkout')==='returned'?'Payment confirmation may take a moment. Scan Area to check your unlocked leads.':p.get('checkout')==='cancelled'?'Checkout cancelled. Scan Area to continue.':'Scan your area to see current demand.');}catch(e){setStatus(e.message);$('demand-scan').disabled=false;}
};
let alertTimer,alertVersion=0;
window.showMowLeadAlerts=async company=>{
 clearTimeout(alertTimer);const version=++alertVersion,target=document.getElementById('dashboard-leads');if(!target)return;
 const refresh=async()=>{if(version!==alertVersion||!target.isConnected)return;
  try{const d=await request({action:'alerts',company_id:company});if(version!==alertVersion||!target.isConnected)return;
   target.innerHTML=`<div class="section-head"><h2>Nearby lawn care demand</h2>${d.new_count?'<span class="pill">'+d.new_count+' new</span>':''}</div>${d.needs_business_zip?'<p>Set your business ZIP to get alerts for nearby homeowners.</p><a class="button primary" href="growth.html">Set up lead alerts</a>':`<p class="demand-count"><strong>${d.count}</strong> homeowner${d.count===1?'':'s'} waiting within 15 miles of ${esc(d.zip)}.</p><p role="status" aria-live="polite">${d.new_count?d.new_count+' new lead'+(d.new_count===1?'':'s')+' since your last Growth scan.':'No new leads since your last Growth scan.'}</p><a class="button primary" href="growth.html?zip=${esc(d.zip)}&radius=15">View nearby leads</a><p class="help">$5 per new lead, up to $39 per bundle. Initial local bundle free after registration; ongoing leads included free with Grow and Scale.</p><p class="lead-disclaimer">${disclaimer}</p>`}`;
  }catch(e){if(version===alertVersion&&target.isConnected){target.innerHTML='<h2>Nearby lawn care demand</h2><p role="status">Lead alerts could not refresh.</p><button class="button" id="lead-alert-retry">Try again</button><a class="button" href="growth.html">Open Growth</a>';target.querySelector('#lead-alert-retry').onclick=()=>window.showMowLeadAlerts(company);}}
  if(version===alertVersion&&target.isConnected){const tick=()=>{if(version!==alertVersion||!target.isConnected)return;if(document.visibilityState==='visible')void refresh();else alertTimer=setTimeout(tick,60000);};alertTimer=setTimeout(tick,60000);}
 };await refresh();
};
})();
